//! Embedded core terminology.
//!
//! A [`TerminologyProvider`] backed by the FHIR core value sets that can be
//! expanded **offline** — every `compose.include` names a `complete` CodeSystem
//! shipped in the spec bundle, with no filters or nested value-set references.
//! One gzipped map per enabled FHIR version, generated by the
//! `generate-terminology` binary and committed under `packs/` (the same
//! committed-generated-artifact workflow as the schema packs).
//!
//! Its purpose is required-binding validation without a terminology server: a
//! `code` bound to `administrative-gender` must be one of `male | female |
//! other | unknown`, so `masculino` (a Spanish *display*, not a FHIR code) is
//! rejected. Value sets that need a live server (SNOMED, LOINC, filtered
//! includes) are absent from the map; for those the provider returns `Ok(true)`
//! — "not disproved here" — so it never blocks on codes it cannot check.

use crate::effects::{CodedValue, Deferred, TerminologyError, TerminologyProvider, coded_value};
use crate::engine::{ErrorKind, ValidationError};
use async_trait::async_trait;
use flate2::read::GzDecoder;
use helios_fhir::FhirVersion;
use serde_json::Value;
use std::collections::HashMap;
use std::io::Read;
use std::sync::{Arc, OnceLock};

#[cfg(feature = "R4")]
static R4_TX: &[u8] = include_bytes!("../packs/terminology_r4.json.gz");
#[cfg(feature = "R4B")]
static R4B_TX: &[u8] = include_bytes!("../packs/terminology_r4b.json.gz");
#[cfg(feature = "R5")]
static R5_TX: &[u8] = include_bytes!("../packs/terminology_r5.json.gz");
#[cfg(feature = "R6")]
static R6_TX: &[u8] = include_bytes!("../packs/terminology_r6.json.gz");

/// The embedded core value sets for a FHIR version. Parsed on first use;
/// subsequent calls return the shared instance.
pub fn core_terminology(version: FhirVersion) -> Arc<CoreTerminology> {
    match version {
        #[cfg(feature = "R4")]
        FhirVersion::R4 => {
            static TX: OnceLock<Arc<CoreTerminology>> = OnceLock::new();
            Arc::clone(TX.get_or_init(|| Arc::new(CoreTerminology::from_gz(R4_TX, "4.0"))))
        }
        #[cfg(feature = "R4B")]
        FhirVersion::R4B => {
            static TX: OnceLock<Arc<CoreTerminology>> = OnceLock::new();
            Arc::clone(TX.get_or_init(|| Arc::new(CoreTerminology::from_gz(R4B_TX, "4.3"))))
        }
        #[cfg(feature = "R5")]
        FhirVersion::R5 => {
            static TX: OnceLock<Arc<CoreTerminology>> = OnceLock::new();
            Arc::clone(TX.get_or_init(|| Arc::new(CoreTerminology::from_gz(R5_TX, "5.0"))))
        }
        #[cfg(feature = "R6")]
        FhirVersion::R6 => {
            static TX: OnceLock<Arc<CoreTerminology>> = OnceLock::new();
            Arc::clone(TX.get_or_init(|| Arc::new(CoreTerminology::from_gz(R6_TX, "6.0"))))
        }
        // Feature unification can add FhirVersion variants beyond the packs
        // this crate was built with: `helios-audit`'s R5/R6 features enable
        // `helios-fhir/R4B` without enabling this crate's `R4B` (#1367).
        #[allow(unreachable_patterns)]
        other => panic!(
            "no terminology pack embedded for FHIR version {other:?} — enable the matching \
             helios-fhir-validator feature"
        ),
    }
}

/// Codes of one value set, indexed by code → the systems that define it here.
type ValueSetCodes = HashMap<String, Vec<String>>;

/// An offline terminology provider over the embedded core value sets.
pub struct CoreTerminology {
    /// The FHIR release (`major.minor`) these value sets come from.
    release: &'static str,
    /// Value-set URL (version-stripped) → its expanded codes.
    sets: HashMap<String, ValueSetCodes>,
}

/// Canonical prefix of the value sets the FHIR core specification defines.
pub const CORE_VALUE_SET_PREFIX: &str = "http://hl7.org/fhir/ValueSet/";

/// The FHIR release (`major.minor`) of a FHIR version string: `4.0.1` →
/// `4.0`, `6.0.0-snapshot1` → `6.0`. `None` when it does not look like one.
pub fn fhir_release(version: &str) -> Option<&str> {
    let mut dots = version.match_indices('.').map(|(i, _)| i);
    let first = dots.next()?;
    let end = dots
        .next()
        .or_else(|| version[first..].find('-').map(|i| first + i))
        .unwrap_or(version.len());
    let release = &version[..end];
    release
        .split('.')
        .all(|part| !part.is_empty() && part.bytes().all(|b| b.is_ascii_digit()))
        .then_some(release)
}

impl CoreTerminology {
    fn from_gz(bytes: &[u8], release: &'static str) -> Self {
        let mut decoder = GzDecoder::new(bytes);
        let mut json = Vec::new();
        decoder
            .read_to_end(&mut json)
            .expect("embedded terminology pack decompresses");
        let pairs: Vec<(String, Vec<(String, String)>)> =
            serde_json::from_slice(&json).expect("embedded terminology pack parses");
        let mut sets = HashMap::with_capacity(pairs.len());
        for (url, codes) in pairs {
            let mut by_code: ValueSetCodes = HashMap::new();
            for (system, code) in codes {
                by_code.entry(code).or_default().push(system);
            }
            sets.insert(url, by_code);
        }
        Self { release, sets }
    }

    /// `Some(true/false)` when the value set is known here; `None` when it is
    /// not embedded (needs a terminology server). `system == None` matches the
    /// code under any system in the set (a bare `code` whose system is implied
    /// by the binding).
    fn contains(&self, value_set: &str, system: Option<&str>, code: &str) -> Option<bool> {
        // A value set pinned to another release is embedded under its pinned
        // URL when a schema in this pack binds it; otherwise it is not judged.
        let set = match self.sets.get(value_set) {
            Some(set) => set,
            None if self.is_other_release(value_set) => return None,
            None => self.sets.get(strip_version(value_set))?,
        };
        let Some(systems) = set.get(code) else {
            return Some(false);
        };
        match system {
            Some(sys) => Some(systems.iter().any(|s| s == sys)),
            None => Some(true),
        }
    }

    /// Whether `value_set` is a core value set pinned to a FHIR release other
    /// than this one (`…/FHIR-version|5.0.0` against the R4 sets): its codes
    /// can differ from this release's.
    fn is_other_release(&self, value_set: &str) -> bool {
        value_set
            .strip_prefix(CORE_VALUE_SET_PREFIX)
            .is_some_and(|rest| {
                rest.split_once('|')
                    .and_then(|(_, version)| fhir_release(version))
                    .is_some_and(|release| release != self.release)
            })
    }

    /// `Some(true)` in-set, `Some(false)` definitely out, `None` can't judge
    /// offline (value set not embedded, or shape not coded). This is the sync
    /// core both `validate_code` and the editor's binding check share.
    fn member(&self, value_set: &str, coded: &CodedValue) -> Option<bool> {
        match coded {
            CodedValue::Code(code) => self.contains(value_set, None, code),
            CodedValue::Coding(coding) => {
                let (system, code) = coding_parts(coding);
                self.contains(value_set, system, code?)
            }
            CodedValue::CodeableConcept(cc) => {
                let codings = cc
                    .get("coding")
                    .and_then(Value::as_array)
                    .filter(|c| !c.is_empty())?;
                let mut saw_false = false;
                for coding in codings {
                    let (system, code) = coding_parts(coding);
                    let Some(code) = code else { continue };
                    match self.contains(value_set, system, code) {
                        Some(true) => return Some(true),
                        Some(false) => saw_false = true,
                        None => return None, // any unembedded coding → can't judge the whole concept
                    }
                }
                saw_false.then_some(false)
            }
        }
    }

    /// Required-binding violations among `deferred`, checked offline against the
    /// embedded core value sets. Bindings whose value set is not embedded (needs
    /// a terminology server) are skipped, not guessed. Lets a synchronous caller
    /// (the resource editor) surface the same binding errors the async effects
    /// pass would, without a terminology server.
    pub fn required_binding_errors(&self, deferred: &[Deferred]) -> Vec<ValidationError> {
        let mut errors = Vec::new();
        for d in deferred {
            let Deferred::Binding {
                path,
                binding,
                value,
                type_hint,
            } = d
            else {
                continue;
            };
            if binding.strength.as_deref() != Some("required") {
                continue;
            }
            let Some(coded) = coded_value(value, type_hint.as_deref()) else {
                continue;
            };
            if self.member(&binding.value_set, &coded) == Some(false) {
                errors.push(ValidationError::new(
                    ErrorKind::TerminologyBinding,
                    path.clone(),
                    format!(
                        "code is not in the required value set '{}'",
                        strip_version(&binding.value_set)
                    ),
                ));
            }
        }
        errors
    }
}

/// Strips a `|version` suffix from a canonical URL (`…/administrative-gender|4.0.1`).
fn strip_version(url: &str) -> &str {
    url.split('|').next().unwrap_or(url)
}

fn coding_parts(coding: &Value) -> (Option<&str>, Option<&str>) {
    (
        coding.get("system").and_then(Value::as_str),
        coding.get("code").and_then(Value::as_str),
    )
}

#[async_trait]
impl TerminologyProvider for CoreTerminology {
    async fn validate_code(
        &self,
        value_set: &str,
        coded: &CodedValue,
    ) -> Result<bool, TerminologyError> {
        // Unknown value set / non-coded shape → not disproved here (`Ok(true)`);
        // only a definite `Some(false)` from `member` is a binding failure.
        Ok(self.member(value_set, coded).unwrap_or(true))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[cfg(feature = "R4")]
    #[tokio::test]
    async fn rejects_a_non_code_but_accepts_the_real_codes() {
        let tx = core_terminology(FhirVersion::R4);
        let vs = "http://hl7.org/fhir/ValueSet/administrative-gender";
        for good in ["male", "female", "other", "unknown"] {
            assert!(
                tx.validate_code(vs, &CodedValue::Code(good.into()))
                    .await
                    .unwrap(),
                "{good} is a valid administrative-gender code"
            );
        }
        // "masculino" is a Spanish display, not a FHIR code.
        assert!(
            !tx.validate_code(vs, &CodedValue::Code("masculino".into()))
                .await
                .unwrap(),
            "masculino is not an administrative-gender code"
        );
    }

    #[cfg(feature = "R4")]
    #[tokio::test]
    async fn unknown_value_set_is_not_disproved() {
        let tx = core_terminology(FhirVersion::R4);
        // A value set that needs a live server is absent from the pack.
        let res = tx
            .validate_code(
                "http://hl7.org/fhir/ValueSet/example-not-embedded",
                &CodedValue::Code("anything".into()),
            )
            .await
            .unwrap();
        assert!(res, "an unembedded value set must not be disproved offline");
    }

    #[test]
    fn fhir_release_is_major_minor() {
        assert_eq!(fhir_release("4.0.1"), Some("4.0"));
        assert_eq!(fhir_release("6.0.0-snapshot1"), Some("6.0"));
        assert_eq!(fhir_release("5.0"), Some("5.0"));
        assert_eq!(fhir_release("2014-03-26"), None);
        assert_eq!(fhir_release("current"), None);
    }

    #[cfg(feature = "R4")]
    #[tokio::test]
    async fn a_core_value_set_of_another_release_is_not_judged() {
        let tx = core_terminology(FhirVersion::R4);
        let code = CodedValue::Code("4.0".into());
        // R4's own FHIR-version value set has only full versions (4.0.1)...
        let r4 = "http://hl7.org/fhir/ValueSet/FHIR-version";
        assert!(!tx.validate_code(r4, &code).await.unwrap());
        assert!(
            !tx.validate_code(&format!("{r4}|4.0.1"), &code)
                .await
                .unwrap()
        );
        // ...while R5's — which a ViewDefinition's binding means, and which
        // the R4 pack embeds for it — also has `4.0`.
        let r5 = format!("{r4}|5.0.0");
        assert!(tx.validate_code(&r5, &code).await.unwrap());
        let bogus = CodedValue::Code("4.9".into());
        assert!(!tx.validate_code(&r5, &bogus).await.unwrap());
        // A release whose value set no schema here needs is not judged by
        // this release's codes.
        assert!(
            tx.validate_code(&format!("{r4}|6.0.0"), &bogus)
                .await
                .unwrap()
        );
    }
}
